// Fail-closed auth, same contract as every other VIO webhook. This endpoint spends no credits
// (Apollo's mixed_people/api_search is free), but it DOES reach a paid vendor with our key and
// returns real people's names to whoever calls it — an open endpoint here leaks a prospect list.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Resolve the product to its ICP, then let the CALLER override the parts a human is allowed to
// change. Rewritten 2026-09-05: the filters used to be hardcoded here, so the only way to search
// for anyone new was to edit and re-import this workflow. The console now sends them.
//
// The shape of the trust boundary matters more than the filter list. Two things are the caller's
// business and two things are not:
//
//   CALLER CHOOSES   titles, seniority, company size, US location, keywords, page, per_page
//   WE DECIDE        the country (United States), that a result must have an email, the per-run
//                    cap, and which product's copy these people will eventually receive
//
// Everything the caller sends is validated against a whitelist and REFUSED on anything unknown --
// never silently dropped. A filter that is quietly ignored is worse than one that errors: the
// operator believes they narrowed the search, sees a plausible list, and pulls the wrong people.
const ICP = {
  oryoniq: {
    product: 'OryonIQ',
    person_titles: ['Capture Manager', 'VP of Business Development',
                    'Director of Business Development', 'Proposal Manager'],
    person_seniorities: ['director', 'vp', 'c_suite'],
    // q_keywords is EMPTY on purpose, and this is a correction rather than an omission. Both ICPs used
    // to default it to 'government contracting' / 'government'. Measured live 2026-09-05: Apollo's
    // q_keywords is a literal full-text match over the person and company record, not an industry
    // filter, and that one phrase collapsed 168,759 matching people to SEVEN. The hardcoded search had
    // therefore been returning almost nobody since it was written, and it looked like a narrow market
    // rather than a broken filter.
    //
    // Targeting is done with titles + seniority + location + company size, which measure 490 matching
    // people for one US state at 51-200 staff. q_keywords stays available to the operator as a
    // deliberate narrowing tool -- it works, it is just far sharper than it reads.
    q_keywords: '',
  },
  visioneerit: {
    product: 'VisioneerIT',
    person_titles: ['CIO', 'CISO', 'Chief Information Officer', 'Chief Information Security Officer',
                    'Director of IT', 'IT Director', 'Director of Information Technology',
                    'IT Program Manager', 'Digital Transformation Lead'],
    person_seniorities: ['director', 'vp', 'c_suite'],
    q_keywords: '',   // see the note on oryoniq above
  },
};

// Apollo's own vocabulary. Anything outside this list is a typo or an attempt at something else;
// either way Apollo would ignore it silently, which is exactly the failure we refuse to have.
const SENIORITIES = ['owner', 'founder', 'c_suite', 'partner', 'vp', 'head', 'director', 'manager'];

// The country is not a filter -- it is a constraint. Sending anywhere else means mailing people
// under a regime (GDPR, CASL) this pilot has not been cleared for, so location is restricted to
// US states rather than merely defaulted to them.
const US_STATES = ['Alabama', 'Alaska', 'Arizona', 'Arkansas', 'California', 'Colorado',
  'Connecticut', 'Delaware', 'District of Columbia', 'Florida', 'Georgia', 'Hawaii', 'Idaho',
  'Illinois', 'Indiana', 'Iowa', 'Kansas', 'Kentucky', 'Louisiana', 'Maine', 'Maryland',
  'Massachusetts', 'Michigan', 'Minnesota', 'Mississippi', 'Missouri', 'Montana', 'Nebraska',
  'Nevada', 'New Hampshire', 'New Jersey', 'New Mexico', 'New York', 'North Carolina',
  'North Dakota', 'Ohio', 'Oklahoma', 'Oregon', 'Pennsylvania', 'Rhode Island', 'South Carolina',
  'South Dakota', 'Tennessee', 'Texas', 'Utah', 'Vermont', 'Virginia', 'Washington',
  'West Virginia', 'Wisconsin', 'Wyoming'];

const MAX_PER_PAGE = 25;    // matches the operator agent's per-run budget ceiling
const MAX_TITLES = 25;
const MAX_PAGE = 50;

const body = $input.first().json || {};

// Require a STRING. String(['oryoniq']) === 'oryoniq', so coercing here would let an array (or
// any object with a matching toString) through a gate whose whole job is to refuse the unknown.
// A gate that coerces is not a gate.
if (typeof body.product !== 'string') {
  throw new Error(`REFUSED: 'product' must be a string, got ${Array.isArray(body.product) ? 'array' : typeof body.product}`);
}
const key = body.product.trim().toLowerCase();
const icp = ICP[key];
if (!icp) {
  throw new Error(`REFUSED: unknown product '${body.product}'. Known: ${Object.keys(ICP).join(', ')}`);
}

const clean = (v, cap) => String(v == null ? '' : v)
  .replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap);

// A caller may send a list as an array or as one comma-separated string, because a text input in
// a browser produces the second and a saved search produces the first.
const asList = (v, field) => {
  if (v === undefined || v === null || v === '') return null;
  if (!Array.isArray(v) && typeof v !== 'string') {
    throw new Error(`REFUSED: '${field}' must be a list or a comma-separated string`);
  }
  const arr = Array.isArray(v) ? v : String(v).split(',');
  const out = arr.map((x) => clean(x, 80)).filter(Boolean);
  return out.length ? out : null;
};

// Two fields cannot use the comma rule above, because in both of them a comma means something
// else. Splitting them naively is not a crash -- it silently searches for the wrong thing, which
// is the failure mode this whole node exists to prevent.
const asBandList = (v, field) => {
  if (v === undefined || v === null || v === '') return null;
  if (Array.isArray(v)) {
    const a = v.map((x) => clean(x, 40)).filter(Boolean);
    return a.length ? a : null;
  }
  if (typeof v !== 'string') throw new Error(`REFUSED: '${field}' must be a list or a ';'-separated string`);
  const out = String(v).split(';').map((x) => clean(x, 40)).filter(Boolean);
  return out.length ? out : null;
};

const asLocationList = (v, field) => {
  if (v === undefined || v === null || v === '') return null;
  if (Array.isArray(v)) return asList(v, field);
  if (typeof v !== 'string') throw new Error(`REFUSED: '${field}' must be a list or a comma-separated string`);
  // "Texas, US" is ONE entry whose comma belongs to the entry. Strip the country suffix before
  // splitting, or 'Texas, US' becomes the two entries 'Texas' and 'US'.
  return asList(v.replace(/,\s*(United States|USA|US)\b/gi, ''), field);
};

// ---- titles ---------------------------------------------------------------------------------
const person_titles = asList(body.person_titles ?? body.titles, 'person_titles') || icp.person_titles;
if (person_titles.length > MAX_TITLES) {
  throw new Error(`REFUSED: ${person_titles.length} job titles; at most ${MAX_TITLES}. A title list this long is not a search, it is the absence of one.`);
}

// ---- seniority ------------------------------------------------------------------------------
let person_seniorities = asList(body.person_seniorities ?? body.seniorities, 'person_seniorities');
if (person_seniorities) {
  person_seniorities = person_seniorities.map((s) => s.toLowerCase().replace(/[\s-]+/g, '_'));
  const bad = person_seniorities.filter((s) => SENIORITIES.indexOf(s) === -1);
  if (bad.length) {
    throw new Error(`REFUSED: unknown seniority ${JSON.stringify(bad)}. Known: ${SENIORITIES.join(', ')}`);
  }
} else {
  person_seniorities = icp.person_seniorities;
}

// ---- company size ---------------------------------------------------------------------------
// Apollo takes free-form "min,max" bands rather than a fixed enum, so the FORMAT is what gets
// checked. An inverted or absurd range is refused: Apollo would return an empty list and the
// operator would read that as "nobody matches" rather than "you typed it backwards".
// A comma lives INSIDE a band ("51,200"), so it cannot also separate bands -- splitting a plain
// string on commas turned one band into two one-wide ones ("51,51" and "200,200") and quietly
// searched for companies of exactly 51 and exactly 200 staff. Bands are separated by ';'.
let ranges = asBandList(body.organization_num_employees_ranges ?? body.employee_ranges, 'organization_num_employees_ranges');
if (ranges) {
  ranges = ranges.map((r) => {
    const flat = r.replace(/\s/g, '');
    const m = /^(\d{1,7}),(\d{1,7})$/.exec(flat) || /^(\d{1,7})$/.exec(flat);
    if (!m) throw new Error(`REFUSED: company size '${r}' must look like '51,200'`);
    const lo = Number(m[1]);
    const hi = m[2] === undefined ? lo : Number(m[2]);
    if (hi < lo) throw new Error(`REFUSED: company size '${r}' runs backwards (${lo} to ${hi})`);
    return `${lo},${hi}`;
  });
}

// ---- location -------------------------------------------------------------------------------
// Apollo matches a person location as "<State>, US"; a bare state name does not reliably hit.
// Translating here means the console can offer a plain state name and still get real results.
let person_locations = asLocationList(body.person_locations ?? body.locations, 'person_locations');
if (person_locations) {
  person_locations = person_locations.map((raw) => {
    const v = raw.replace(/,\s*(US|USA|United States)$/i, '').trim();
    if (/^(United States|USA|US)$/i.test(v)) return 'United States';
    const hit = US_STATES.filter((s) => s.toLowerCase() === v.toLowerCase())[0];
    if (!hit) {
      throw new Error(`REFUSED: '${raw}' is not a US state. This campaign is United States only -- a lead outside it has not been cleared for outreach.`);
    }
    return `${hit}, US`;
  });
} else {
  person_locations = ['United States'];
}

// ---- keywords, paging -----------------------------------------------------------------------
const kwGiven = body.q_keywords !== undefined || body.keywords !== undefined;
const q_keywords = kwGiven ? clean(body.q_keywords ?? body.keywords, 160) : icp.q_keywords;

// The line between refusing and forgiving, and it is drawn on purpose:
//
//   REFUSE anything that changes WHO gets contacted -- an unknown seniority, a foreign country,
//          a backwards size band. Silently ignoring one of those puts strangers in front of a
//          real salesperson while the operator believes they narrowed the search.
//   FORGIVE anything that only changes HOW MANY come back. A nonsense page size cannot contact
//          the wrong person; it can only return a different number of the right ones, and the
//          number that came back is visible in the result. Falling back keeps a caller that emits
//          a null or a string -- the operator agent does -- from failing over a harmless value.
//
// Infinity takes the DEFAULT rather than the cap: the conservative answer for a nonsense value.
const numOr = (v, dflt, lo, hi) => {
  if (v === undefined || v === null || v === '') return dflt;
  const n = Number(v);
  if (!Number.isFinite(n) || n < lo) return dflt;
  return Math.min(Math.floor(n), hi);
};
const page = numOr(body.page, 1, 1, MAX_PAGE);
const asked = Number(body.per_page ?? body.limit);
const per_page = numOr(body.per_page ?? body.limit, 10, 1, MAX_PER_PAGE);

const apollo_body = { person_titles, person_locations, person_seniorities, page, per_page };
if (q_keywords) apollo_body.q_keywords = q_keywords;
if (ranges) apollo_body.organization_num_employees_ranges = ranges;

return { json: {
  source_config: key,
  product: icp.product,
  per_page,
  page,
  capped: Number.isFinite(asked) && asked > MAX_PER_PAGE,
  // Echoed so the console can show exactly what ran and save it as a named search. A saved search
  // that stored the operator's typing rather than the resolved filters would replay differently
  // from the run it was saved off.
  filters_used: {
    person_titles, person_seniorities, person_locations,
    q_keywords: q_keywords || null,
    organization_num_employees_ranges: ranges || null,
    page, per_page,
    defaults_applied: [
      (body.person_titles ?? body.titles) ? null : 'person_titles',
      (body.person_seniorities ?? body.seniorities) ? null : 'person_seniorities',
      (body.person_locations ?? body.locations) ? null : 'person_locations',
      kwGiven ? null : 'q_keywords',
    ].filter(Boolean),
  },
  apollo_body,
} };

// Filter Apollo's free results down to emailable leads and shape them onto the Sheet's column
// names. Mirrors engine.py: `[p for p in people if p.get('has_email')][:limit]`.
//
// NOTHING here spends a credit. has_email / has_direct_phone are FLAGS on the free search — the
// actual address requires people/match, which is a separate, human-gated step and is deliberately
// not reachable from this workflow.
const meta = $('Resolve ICP').first().json;
const resp = $input.first().json || {};
const people = Array.isArray(resp.people) ? resp.people : [];

const orgName = (p) => ((p.organization || {}).name)
  || ((p.account || {}).name) || p.organization_name || 'their firm';

// VERIFIED against the live API 2026-08-22: Apollo's FREE mixed_people/api_search does NOT
// return a company domain. `organization` carries `name` plus has_* booleans and nothing else —
// no primary_domain, no website_url. The extraction below is kept for paid/enriched shapes, but
// on the free path it correctly yields ''.
//
// This contradicts the comment on engine.py's org_domain(), which states the domain is "free — it
// comes back on Apollo's unpaid search". It does not. The consequence is real: company_domain
// drives Sendr's `gifSource: dynamic-website`, so without it the personalized page silently falls
// back to a generic preview instead of screenshotting the lead's own site.
const orgDomain = (p) => {
  const org = p.organization || p.account || {};
  const raw = org.primary_domain || org.website_url || '';
  if (!raw) return '';
  return String(raw).replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0];
};

// Apollo returns has_direct_phone as a STRING on the free tier — literally
// "Maybe: please request direct dial via people/bulk_match". Boolean() on that is `true`, which
// would mark every lead as having a confirmed direct dial. It is a maybe, and it must say so.
const phoneState = (v) => {
  if (v === true) return true;
  if (typeof v === 'string' && /^maybe/i.test(v.trim())) return 'maybe';
  return Boolean(v);
};

const clean = (v, cap = 200) => (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap) : '');

const survivors = people.filter((p) => p && p.has_email).slice(0, meta.per_page);

const leads = survivors.map((p) => ({
  source_config: meta.source_config,
  apollo_id: clean(p.id, 64),
  first_name: clean(p.first_name, 80) || 'there',
  // Free search withholds the surname — only `last_name_obfuscated` (e.g. "B.") comes back.
  last_name: clean(p.last_name, 80),
  last_name_obfuscated: clean(p.last_name_obfuscated, 80),
  title: clean(p.title, 120) || '(role)',
  company: clean(orgName(p), 160),
  company_domain: clean(orgDomain(p), 160),
  has_email: Boolean(p.has_email),
  has_phone: phoneState(p.has_direct_phone),
  linkedin_url: clean(p.linkedin_url, 240),
  contact_email: '',        // stays empty — revealing costs a credit and is human-gated
}));

return [{ json: {
  source_config: meta.source_config,
  product: meta.product,
  // Echoed all the way out so the console can show exactly what ran and save it as a named search.
  // It reached Resolve ICP and stopped there, so the response said filters_used: null while the
  // search had in fact used a full filter set.
  filters_used: meta.filters_used,
  returned_by_apollo: people.length,
  total_entries: resp.pagination ? resp.pagination.total_entries : (resp.total_entries ?? null),
  emailable: leads.length,
  dropped_no_email: people.length - survivors.length,
  per_page: meta.per_page,
  limit_capped: Boolean(meta.capped),
  credits_spent: 0,
  company_domain_available: leads.some((l) => l.company_domain !== ''),
  leads,
} }];

// Normalise for the caller and restate the boundary in the response itself — whoever reads this
// should not have to infer what did and did not happen. Strings are control-char scrubbed: n8n's
// lastNode response serialises with RAW control characters, which strict JSON parsers reject
// (found live 2026-08-16).
const scrub = (v) => Array.isArray(v) ? v.map(scrub)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, scrub(x)]))
  : (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);

const r = $input.first().json;
return [{ json: scrub({
  ok: true,
  ran: ['resolve_filters', 'apollo_search_free', 'filter_has_email'],
  ...r,
  note: 'Apollo free search only. No lead credit was spent and no email address was revealed — '
      + 'revealing is people/match, a separate human-gated step this workflow cannot reach.',
}) }];
